function(callback) {
			var seen = [];
			var rows = [];
			for (var i = 0; i < 20; i++)
				rows.push('a' + i + ',b' + i + ',c' + i);
			var input = 'Col1,Col2,Col3\r\n' + rows.join('\r\n');
			Papa.parse(input, {
				header: true,
				chunkSize: 10,	// force many chunks so the header row is crossed once
				transformHeader: function(header) {
					seen.push(header);
					return header.toLowerCase();
				},
				complete: function() {
					callback(seen);
				}
			});
		}
